	                                ,GE.InvoicingPartyPlantId
	                                ,GE.InvoicingByAddress
	                                ,GE.DeliveryPartyPlantId
	                                ,GE.DeliveryByAddress
	                                ,GE.Description
	                                ,GE.PackageQty
	                                ,GE.ModeofTransport
	                                ,GE.Bill
	                                ,GE.PersonName
	                                ,MobileNo
	                                ,GE.Remarks
	                                ,GE.AddedBy
	                                ,p.UserName
	                                ,p.Id,ei.FirstName
                                FROM TRN.GateEntry GE
                                left Join hkp.Party p on p.Id=GE.PartyId
