        public void Delete(string id)
        {
            var rdBuilder = new System.Text.StringBuilder();
            var builderSql = "";
            try
            {
                var detail = Convert.ToBoolean(_inventoryReceiveRepository.SqlQuery<int>(@"IF EXISTS(SELECT 1 FROM(SELECT Id FROM TRN.InventoryReceiveDetail WHERE InventoryReceiveId='" + id + @"') AS A )SELECT 1 ELSE SELECT 0 RETURN").First());
                var service = Convert.ToBoolean(_inventoryReceiveRepository.SqlQuery<int>(@"IF EXISTS(SELECT 1 FROM(SELECT Id FROM TRN.InventoryService WHERE InventoryReceiveId='" + id + @"') AS A )SELECT 1 ELSE SELECT 0 RETURN").First());
                if (!detail && !service)
                {
                    var data = base.Find(id);
                    if (data.IsNull()) throw new CustomException(ServiceResources.RecordNoLonger);
                    var POServiceData = _pOGGRNMapRepository.Query(r => r.GRNId == id).Select().ToList();
                    var GRNAcceptaceServiceData = _gRNAcceptanceMapRepository.Query(r => r.GRNId == id).Select().ToList();
                    if (POServiceData.IsNotNull())
                    {
                        foreach (var item in POServiceData)
                        {
                            builderSql = @"update trn.POGGRNMap set GRNId=NULL where GRNId='" + data.Id + @"'";
                            rdBuilder.Append(builderSql);
                            _sqlRepository.ExecuteSqlCommand(rdBuilder.ToString());
                            _pOGGRNMapRepository.Delete(item.Id);

                        }


                        //foreach (var item in voucherdetail)
                        //{
                        //	var glTransactionDetail = _gLTransactionDetailRepository.Query(r => r.VoucherDetailId == item.Id).Select().FirstOrDefault();
                        //	if (glTransactionDetail != null)
                        //	{
                        //		_gLTransactionDetailRepository.Delete(item.Id);
                        //	}
                        //	var rdBuilder = new System.Text.StringBuilder();
                        //	var builderSql = @"UPDATE [TRN].VoucherDetail SET BankChargeId=NULL WHERE Id='" + item.Id + "'";
                        //	rdBuilder.Append(builderSql);
                        //	_sqlRepository.ExecuteSqlCommand(rdBuilder.ToString());

                        //	_voucherDetailRepository.Delete(item.Id);
                        //}

                    }
                    if (GRNAcceptaceServiceData.IsNotNull())
                    {
                        foreach (var item in GRNAcceptaceServiceData)
                        {

                            builderSql = @"update trn.GRNAcceptanceMap set GRNId=NULL where GRNId='" + data.Id + @"'";
                            rdBuilder.Append(builderSql);
                            _sqlRepository.ExecuteSqlCommand(rdBuilder.ToString());
                            _gRNAcceptanceMapRepository.Delete(item.Id);

                        }

                    }
                    base.Delete(data);
                    rdBuilder.Append(builderSql);
                    _unitOfWork.SaveChanges();

                }
                else throw new CustomException("Please delete first line item.");
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Product.ToString()));
            }
        }


        public IEnumerable<object> GetListForHold(string plantId, string PoType, string Status, string vendorId)
        {
            var Sql = "";
            try
            {
                if (Status == "PO")
                {
                    Sql = @"--DECLARE @plantId VARCHAR(10)='" + plantId + @"';                                     
                    Select* from(
                     SELECT ROW_NUMBER() OVER (ORDER BY  IR.Id) AS SiNo, IR.Id, REPLACE(CONVERT(CHAR(11), IR.PODate, 106), ' ', '-') AS PODate, IR.CompanyGroupId, IR.CompanyId, IR.PlantId, IR.PartyId, P.Code AS PartyCode, P.UserName AS PartyName
	                                , CP.UserName AS PartyAccountGroupName,ISNULL(Pr.UserName ,'') CustomerName,ISNULL(CON.ContractNo,'') ContractNo
	                                , IR.MaterialStorageId, IR.DocRefNo, REPLACE(CONVERT(CHAR(11), IR.DocDate, 106), ' ', '-') AS DocDate
                                      , IR.CurrencyId, CU.Code AS CurrencyCode, IR.BaseCurrencyId, IR.PaymentTermId, IR.BaseNoOfDays
	                                , REPLACE(CONVERT(CHAR(11), IR.BaseOnDueDate, 106), ' ', '-') AS BaseOnDueDate, REPLACE(CONVERT(CHAR(11), IR.MatureDate, 106), ' ', '-') AS MatureDate
                                        , IR.FixedAssetOrInventory, IR.PODepended,'' PurchaseDocAcceptanceDetailId
                                          , IR.InvoicingPartyPlantId, IPP.UserName AS InvoicingBy, IR.InvoicingByAddress, IR.DeliveryPartyPlantId, DPP.UserName AS DeliveryBy, IR.DeliveryByAddress, IR.IsNonCreditable
	                                , pod.TransactionQty
									,ToleranceQty= case when pod.ToleranceQty<>0 then pod.ToleranceQty else ((pod.TransactionQty*ir.Tolerance)/100) end
									,pod.GRNQty,pod.PurchaseReturnQty, pod.TransactionAmount, pod.BaseAmount, IR.ToCurrencyRate
	                                , S1.UserName AS InvoicingState,S1.Id AS InvoicingStateId , S2.UserName AS DeliveryState, PT.UserName AS PaymentTermName, CP.TaxApplicable, CP.IsTaxApplicableChangeable, IR.IsTaxApplicable
