                                  LEFT JOIN (SELECT A.InventoryReceiveId, A.TransactionUoMId FROM [TRN].[PurchaseOrderDetail] AS A JOIN [TRN].[PurchaseOrder] AS B ON A.InventoryReceiveId=B.Id
                                        WHERE B.PlantId='" + plantId + @"' GROUP BY A.InventoryReceiveId, A.TransactionUoMId HAVING COUNT(A.InventoryReceiveId)> COUNT(A.TransactionUoMId)) AS TU ON TU.InventoryReceiveId=IR.Id
                                  LEFT JOIN [SCS].[UnitOfMeasurement] AS UoM ON TU.TransactionUoMId=UoM.Id
                                  LEFT JOIN (Select count(Id) as CtnId,POID from TRN.PurchaseOrderApprovalLog where Status='Approved' group by POID) as pgl  on pgl.POID=IR.Id
                                  WHERE IR.PlantId='" + plantId + @"' 
                                  AND IR.IsClosed=0 and IRD.QtyStatus=0  AND IR.POType='" + PoType + @"' 
                                  AND pgl.CtnId is not null
								  AND IR.CheckedByStatus='Checked' ANd AuthorizedByStatus='Approved'
                                  Order by IR.PODate ASC";


                return _sqlRepository.GetDataCollection(Sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Product.ToString()));
            }
        }
        public IEnumerable<object> GetListOfPOGateEntry(string CompanyGroupId, string CompanyId, string PlantId, string partyCode)
        {
            try
            {

                var Sql = @"Select 
	                                GE.Id
	                                ,REPLACE(CONVERT(CHAR(11), GE.EntryDate , 106),' ','-') AS EntryDate
	                                ,P.Code PartyCode
	                                ,GE.InvoicingPartyPlantId
	                                ,GE.InvoicingByAddress
	                                ,GE.DeliveryPartyPlantId
	                                ,GE.DeliveryByAddress
	                                ,GE.Description
	                                ,GE.PackageQty
	                                ,GE.ModeofTransport
	                                ,GE.Bill
	                                ,GE.PersonName
	                                ,MobileNo
	                                ,GE.Remarks
	                                ,GE.AddedBy
	                                ,p.UserName
	                                ,p.Id
                                FROM TRN.GateEntry GE
                                left Join hkp.Party p on p.Id=GE.PartyId
                                Where GE.CompanyGroupId='" + CompanyGroupId + "' AND GE.CompanyId='" + CompanyId + "' AND GE.PlantId='" + PlantId + "' AND GE.FlagStatus='Ok' and p.Id='" + partyCode + "' " +
                                " and GE.GateEntryType IN('Vendor','Director')and GE.Id  not in(select GateEntryNo from TRN.InventoryReceive where GateEntryNo is not null) and GE.Id  not in(select GateEntryNo from [TRN].[ServiceAcknowledgementMaster] where GateEntryNo is not null) " +
                                "and GE.Id  not in(select GateEntryNo from [TRN].[GatePassMaster] where GateEntryNo is not null)" +
                                "Order By GE.EntryDate DESC";
                //AND GE.Id not in(select GateEntryNo from trn.InventoryReceive)
                return _sqlRepository.GetDataCollection(Sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Product.ToString()));
            }
        }




