            //range = wTable.Rows[ROW].Cells[COL].AddParagraph().AppendText("HSN NO");
            //range.ApplyCharacterFormat(FontBold);
            //int colHSNCode = COL; COL++;
            //wTable.Rows[ROW].Cells[colChar3].Width = 45;


