                //					WHERE convert(Date,II.IssueDate) = '" + toDate + @"' AND II.PlantId='" + identity.PlantId + @"'  GROUP BY IID.InventoryMaterialId
                //					) IFD On IFD.InventoryMaterialId=IM.Id

                //		left join (select IID.InventoryMaterialId, Sum(IID.TransactionQty) IssueQty 
                //					FROM TRN.InventoryIssueDetail IID  
                //					LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 
                //					--LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId=IID.Id
                //				WHERE convert(Date,II.IssueDate) BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' AND II.PlantId='" + identity.PlantId + @"' GROUP BY IID.InventoryMaterialId
                //				) IFD1 On IFD1.InventoryMaterialId=IM.Id
                //                             where IM.PlantId='" + identity.PlantId + @"' AND MM.UserName is not null --AND MM.UserName like '%Bed Sheet%'
                //				--AND isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0)> 0
                //			    and isnull(opbal2.TransactionQty,0)>0
                //				and isnull(IFD1.IssueQty,0)>0
                //		GROUP BY 
                //		MT.UserName 
                //		,MGM.UserName 			
                //		,MM.UserName 					 
                //		,ART.StandardName 	
                //		,FCV.UserName 
                //		,SCV.UserName 
                //		,TCV.UserName";


                var sql = @"SELECT                    
							  isnull(MT.UserName,'') MaterialType
							, isnull(MGM.UserName,'') AS MaterialGroupMasterName						
							, isnull(MM.UserName,'') MaterialMasterName					 
							,isnull( ART.StandardName,'') ArticleName		
							, ISNULL(FCV.UserName,'') AS FirstCharacteristicsValue
							, ISNULL(SCV.UserName,'') AS SecondCharacteristicsValue
							, ISNULL(TCV.UserName,'') AS ThirdCharacteristicsValue 	

							,sum(isnull(opbal.TransactionQty,0))-sum(isnull(IFD3.OpeningIssueQty,0)) As OpeningBalance	
							,Round(sum(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)) / ISNULL(NULLIF(sum(isnull(opbal.TransactionQty,0))-sum(isnull(IFD3.OpeningIssueQty,0)),0), 1),2)   AS OpeningBalanceUnitPrice
							,sum(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)) AS OpeningBalanceAmount

							,sum(isnull(opbal1.TransactionQty,0)) ReceivedForTheDay
							,Round(sum(Isnull(opbal1.TotalMaterialBooksCurrencyAmount,0)) / ISNULL(NULLIF(sum(isnull(opbal1.TransactionQty,0)),0), 1),2) AS ReceivedForTheDayUnitPrice
							,sum(Isnull(opbal1.TotalMaterialBooksCurrencyAmount,0)) AS ReceivedForTheDayAmount

							,sum(isnull(opbal2.TransactionQty,0)) ReceivedForThePeriod
							,Round(sum(isnull(opbal2.TotalMaterialBooksCurrencyAmount,0))/ ISNULL(NULLIF(sum(isnull(opbal2.TransactionQty,0)),0), 1),2) AS  ReceivedForThePeriodUnitPrice
							,sum(isnull(opbal2.TotalMaterialBooksCurrencyAmount,0)) AS ReceivedForThePeriodAmount

				                        ,sum(isnull(IFD3.OpeningIssueQty,0)) OpeningIssueQty
							,Round(sum(isnull(IFD3.PolicyAmount,0))/ ISNULL(NULLIF(sum(isnull(IFD3.OpeningIssueQty,0)),0), 1),2) AS OpeningIssueQtyUnitPrice
							,sum(isnull(IFD3.PolicyAmount,0)) OpeningIssueQtyAvgAmount

							,sum(isnull(IFD.IssueQty,0)) IssueForTheDay
							,Round(sum(isnull(IFD.PolicyAmount,0))/ ISNULL(NULLIF(sum(isnull(IFD.IssueQty,0)),0), 1),2) AS IssueForTheDayUnitPrice
							,sum(isnull(IFD.PolicyAmount,0)) IssueForTheDayAmount

							,sum(isnull(IFD1.IssueQty,0)) IssueForThePeriod	
							,Round(sum(isnull(IFD1.PolicyAmount,0)) / ISNULL(NULLIF(sum(isnull(IFD1.IssueQty,0)),0), 1),2) AS IssueForThePeriodUnitPrice
							,sum(isnull(IFD1.PolicyAmount,0)) IssueForThePeriodAmount	

							,(sum(isnull(opbal.TransactionQty,0))-sum(isnull(IFD3.OpeningIssueQty,0)) + sum(isnull(opbal2.TransactionQty,0)))-sum(isnull(IFD1.IssueQty,0)) Closing							
							,(sum(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)) + sum(isnull(opbal2.TotalMaterialBooksCurrencyAmount,0)))-sum(isnull(IFD1.PolicyAmount,0)) ClosingAmount
							,Round(((sum(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)) + sum(isnull(opbal2.TotalMaterialBooksCurrencyAmount,0)))-sum(isnull(IFD1.PolicyAmount,0))) / ISNULL(NULLIF( ((sum(isnull(opbal.TransactionQty,0))-sum(isnull(IFD3.OpeningIssueQty,0)) + sum(isnull(opbal2.TransactionQty,0)))-sum(isnull(IFD1.IssueQty,0))),0), 1),2) ClosingUnitPrice
						from TRN.InventoryMaterial AS IM
						left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
						LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
						LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
						LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
						LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
						LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
						LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
						LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
						LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
						--left jOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId=IM.Id	
						--left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON IRD.TransactionUoMId=TUoM.Id
						--left JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId=IR.Id
						--left JOIN [SCS].[Currency] AS CU ON IR.CurrencyId=CU.Id
						LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
						left join(SELECT IRD.InventoryMaterialId, Sum(IRD.TransactionQty) AS TransactionQty,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
									FROM  [TRN].[InventoryReceiveDetail] IRD
									LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
									where convert(Date,IR.GRNDate) < '" + fromDate + @"'  group By IRD.InventoryMaterialId) AS opbal ON opbal.InventoryMaterialId=IM.Id AND IM.PlantId='" + identity.PlantId + @"'

						left join(SELECT IRD.InventoryMaterialId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
									FROM  [TRN].[InventoryReceiveDetail] IRD
									LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
									where convert(Date,IR.GRNDate) = '" + toDate + @"'  group By IRD.InventoryMaterialId) AS opbal1 ON opbal1.InventoryMaterialId=IM.Id AND IM.PlantId='" + identity.PlantId + @"'

						left join(SELECT IRD.InventoryMaterialId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
									FROM  [TRN].[InventoryReceiveDetail] IRD
									LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
									where convert(Date,IR.GRNDate)		
									BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' group By IRD.InventoryMaterialId) AS opbal2 ON opbal2.InventoryMaterialId=IM.Id AND IM.PlantId='" + identity.PlantId + @"'

				                    left join (select IID.InventoryMaterialId, Sum(IID.TransactionQty) OpeningIssueQty, Sum(IID.PolicyAmount) PolicyAmount
									FROM TRN.InventoryIssueDetail IID  
									LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 									
									WHERE convert(Date,II.IssueDate) < '" + fromDate + @"' AND II.PlantId='" + identity.PlantId + @"' GROUP BY IID.InventoryMaterialId
									) IFD3 On IFD3.InventoryMaterialId=IM.Id
						left join (select IID.InventoryMaterialId, Sum(IID.TransactionQty) IssueQty , Sum(IID.PolicyAmount) PolicyAmount
									FROM TRN.InventoryIssueDetail IID  
									LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 
									--LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId=IID.Id
									WHERE convert(Date,II.IssueDate) = '" + toDate + @"' AND II.PlantId='" + identity.PlantId + @"'  GROUP BY IID.InventoryMaterialId
									) IFD On IFD.InventoryMaterialId=IM.Id

						left join (select IID.InventoryMaterialId, Sum(IID.TransactionQty) IssueQty , Sum(IID.PolicyAmount) PolicyAmount
									FROM TRN.InventoryIssueDetail IID  
									LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 
									--LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId=IID.Id
								WHERE convert(Date,II.IssueDate) BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' AND II.PlantId='201816' GROUP BY IID.InventoryMaterialId
								) IFD1 On IFD1.InventoryMaterialId=IM.Id
				                             where IM.PlantId='" + identity.PlantId + @"' AND MM.UserName is not null --AND MM.UserName like '%Bed Sheet%'
								--AND isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0)> 0
							    --and isnull(opbal2.TransactionQty,0)>0
								--and isnull(IFD1.IssueQty,0)>0
						GROUP BY 
						MT.UserName 
						,MGM.UserName 			
						,MM.UserName 					 
						,ART.StandardName 	
						,FCV.UserName 
						,SCV.UserName 
						,TCV.UserName";

                //var sql = @"select 
                //		isnull((case when row_number() over (partition by IRD.Id  order by (select NULL)) = 1 then IRD.Id end),'') as Id
                //		,(case when row_number() over (partition by IRD.Id  order by (select NULL)) = 1 then REPLACE(CONVERT(CHAR(11), IR.GRNDate, 106),' ','-') end) as RcvDate	
                //		,(case when row_number() over (partition by IRD.Id  order by (select 1)) = 1 then IRD.TransactionQty end) as RcvQty		
                //		,(case when row_number() over (partition by IRD.Id  order by (select 1)) = 1 then IRD.MaterialTranRate end) as RcvRate
                //		,(case when row_number() over (partition by IRD.Id  order by (select NULL)) = 1 then IRD.MaterialTranAmount end) as RcvAmount                             
                //		,REPLACE(CONVERT(CHAR(11), II.IssueDate	, 106),' ','-') IssueDate						
                //		,(case when row_number() over (partition by IRD.Id  order by (select NULL)) = 1 then IH.InventoryReceiveDetailId end) as InventoryReceiveDetailId
                //		,II.Id IssueNo
                //		,IH.Qty IssueQty
                //		,IH.Rate
                //		,IH.Qty*IH.Rate AS IssueAmount 
                //		,(case when row_number() over (partition by IRD.Id  order by (select NULL)) = 1 then B.BalanceQty end) as BalanceQty
                //		,(case when row_number() over (partition by IRD.Id  order by (select NULL)) = 1 
                //			  THEN null
                //		      WHEN B.BalanceQty > 0 
                //		      THEN IRD.MaterialTranRate else null
                //		  end) as BalanceRate
                //		,(case when row_number() over (partition by IRD.Id  order by (select NULL)) = 1 then (B.BalanceQty *IRD.MaterialTranRate) end) as BalanceAmount
                //		FROM TRN.InventoryMaterial AS IM
                //		left JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId=MM.Id
                //		LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
                //		LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
                //		LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
                //		LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
                //		LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
                //		LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
                //		LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
                //		LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
                //		left jOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId=IM.Id	
                //		left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON IRD.TransactionUoMId=TUoM.Id
                //		left JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId=IR.Id
                //		left JOIN [SCS].[Currency] AS CU ON IR.CurrencyId=CU.Id
                //		LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
                //		LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryReceiveDetailId=IRD.ID --IH.InventoryIssueDetailId=IID.Id
                //		LEFT JOIN  TRN.InventoryIssueDetail IID on IID.ID=IH.InventoryIssueDetailId
                //		LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 

                //		LEFT JOIN ( select IH.InventoryReceiveDetailId,(Sum(distinct IRD.TransactionQty)-Sum(Isnull(Ih.Qty,0))) BalanceQty 
                //		            from  [TRN].[InventoryReceiveDetail] AS IRD 
                //				    LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryReceiveDetailId=IRD.ID 
                //					LEFT JOIN  TRN.InventoryIssueDetail IID on IID.ID=IH.InventoryIssueDetailId
