                //					) B ON B.InventoryReceiveDetailId=IRd.Id
                //		where  --II.IssueDate is not null	AND IH.InventoryReceiveDetailId is not null
                //			  --And II.Id is not null And IH.Qty is not null	ANd IH.Rate is not null
