        public void GRNChecked(string GRNId, string PoValue, string CheckedStataus, string AuthorizedBy, string CheckedRejectReason)
        {

            try
            {
                var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
                if (identity.EmployeeId == AuthorizedBy)
                {
                    throw new CustomException("Please select Another Id");
                }
                var AuthorizedById = "null";
                var AuthorizedByStatus = "";
                PoValue = "0";
                var Id = GetPK();
                if (CheckedStataus == "Checked")
                {
                    if (AuthorizedBy == null || AuthorizedBy == "")
                    {
                        throw new CustomException("Select Approved By");
                    }
                    AuthorizedById = AuthorizedBy;
                    AuthorizedByStatus = "For Approval";
                }
                //else if (CheckedStataus == "Hold")
                //{
                //	if (AuthorizedBy == null || AuthorizedBy == "")
                //	{
                //		throw new CustomException("Select Approved By");
                //	}
                //	AuthorizedById = AuthorizedBy;

                //}
                //else if (CheckedStataus == "Reject")
                //{
                //	if (AuthorizedBy == null || AuthorizedBy == "")
                //	{
                //		throw new CustomException("Select Approved By");
                //	}
                //	AuthorizedById = AuthorizedBy;

                //}
                else
                {
                    AuthorizedById = null;

                }
                var Status = CheckedStataus;

                // var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
                var ip = identity.IPAddress;
                var updatedDate = Convert.ToDateTime(DateTime.Now).ToString();
                var AddedBy = identity.Name;
                var ApprovedBy = identity.EmployeeId;
                var AddedDate = Convert.ToDateTime(DateTime.Now).ToString();
                var CompanyGroupId = identity.CompanyGroupId;
                var CompanyId = identity.CompanyId;
                var PlantId = identity.PlantId;
                // string _sql = "Update TRN.PurchaseOrder set IsApproved='0',CheckedByStatus='" + Status + "',AuthorizedBy='" + AuthorizedById + "' where id='" + PoId + "'";
                //_sqlRepository.ExecuteSqlCommand(_sql);
                string _sql2 = "";
                if (AuthorizedById != null)
                {
                    _sql2 = "Update TRN.InventoryReceive set IsApproved='0',CheckedByStatus='" + Status + "',AuthorizedBy='" + AuthorizedById + "',AuthorizedByStatus='" + AuthorizedByStatus + "',  CheckedHoldRejectReason='" + CheckedRejectReason + "' where Id='" + GRNId + "'";

                }
                else
                {
                    _sql2 = "Update TRN.InventoryReceive set IsApproved='0',CheckedByStatus='" + Status + "',CheckedHoldRejectReason='" + CheckedRejectReason + "' where Id='" + GRNId + "'";

                }
                _sqlRepository.ExecuteSqlCommand(_sql2);

                string _sql1 = "Insert into TRN.GRNApprovalLogTbl(Id," +
                "CompanyGroupId," +
                "CompanyId," +
                "PlantId," +
                "ApprovedBy," +
                "Date," +
                "POValue," +
                "Status," +
                "AddedBy," +
                "AddedDate," +
                "AddedFromIp," +
                "GRNId) " +
                "values ('" + Id + "'," +
                "'" + CompanyGroupId + "'," +
                "'" + CompanyId + "'," +
                "'" + PlantId + "'," +
                "'" + ApprovedBy + "'," +
                "'" + AddedDate + "'," +
                "'" + PoValue + "'," +
                "'" + Status + "'," +
                "'" + AddedBy + "'," +
                "'" + AddedDate + "'," +
                "'" + ip + "'," +
                "'" + GRNId + "')";
                _sqlRepository.ExecuteSqlCommand(_sql1);

            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Product.ToString()));
            }
        }
