        #region Grn IssueRequest and Issue

        public IEnumerable<object> IssueSlipFilter()
        {
            try
            {
                var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
                var sql = @"Select 
                           
                            isnull(En.Username,'') As EntityName
                            ,MRM.EntityId
                            ,isnull(Bu.Code,'') AS Code
                            ,isnull(Bu.UserName,'') As UserName
                            ,isnull(Us.FullName,'') As AddedBy
                            ,isnull(MRM.Id,'') As RequisitionNo
                            ,isnull(MRD.Id,'') As RequisitionDetailNo
                            ,MRD.ArticleId
                            ,Isnull(Dp.UserName,'') DepartmentName
							,isnull(MGM.UserName,'') MaterialMasterGroupName
							,Isnull(mm.UserName,'') MaterialMasterName 
	                        ,isnull(ART.StandardName,'') StandardName
							,isnull(MT.UserName,'') AS MaterialType
	                        ,MRD.FirstCharacteristicsId
	                        ,FC.UserName AS FirstCharacteristics
	                        ,MRD.FirstCharacteristicsValueId
	                        ,isnull(FCV.UserName,'') AS FirstCharacteristicsValue
	                        ,MRD.SecondCharacteristicsId
	                        ,SC.UserName AS SecondCharacteristics
	                        ,MRD.SecondCharacteristicsValueId
	                        ,isnull(SCV.UserName,'') AS SecondCharacteristicsValue
	                        ,MRD.ThirdCharacteristicsId
	                        ,TC.UserName AS ThirdCharacteristics
	                        ,MRD.ThirdCharacteristicsValueId
	                        ,isnull(TCV.UserName,'') AS ThirdCharacteristicsValue
                            ,MRD.Id AS RequisitionDetailId
                            --,outIDR.TransactionQty
	                        ,isnull(outIDR.RejectionQty,0) RejectionQty1
	                        ,0 ApprovedQty
                            ,outIDR1.TotalQty
                            --,isnull(Appnext.Valid,0) Valid
							--,isnull(Appnext.RejectionQty1,0) RejectionQty1
							--,isnull((Valid+RejectionQty1),0) TotalQty
                          ,IssuedQtyOut.IssueQty AS IssuedQty
                          ,0 RequestedQty
                          ,0 RejectedQty
                         from [TRN].[MaterialRequsitionDetails] As MRD
                        Left Join  [TRN].[MaterialRequsitionMaster] As MRM On MRD.MaterialReqqusitionMasterId=MRM.Id
                        Left Join [ORG].[Entity] As En On MRM.EntityId=En.Id
                        Left Join [HKP].[Budget] As Bu On Bu.Id=MRD.ActivityId
                        Left JOIN MST.MaterialMaster AS MM ON MRD.MaterialMasterId = MM.Id
                        LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
                        LEFT JOIN MST.MaterialMasterArticle AS ART ON MRD.ArticleId = ART.Id
                        LEFT JOIN HKP.Characteristics AS FC ON MRD.FirstCharacteristicsId = FC.Id
                        LEFT JOIN HKP.Characteristics AS SC ON MRD.SecondCharacteristicsId = SC.Id
                        LEFT JOIN HKP.Characteristics AS TC ON MRD.ThirdCharacteristicsId = TC.Id
                        LEFT JOIN HKP.CharacteristicsValue AS FCV ON MRD.FirstCharacteristicsValueId = FCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS SCV ON MRD.SecondCharacteristicsValueId = SCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS TCV ON MRD.ThirdCharacteristicsValueId = TCV.Id
                        LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MRD.TransactionUoMId = TUoM.Id
                        LEFT JOIN [SEC].[User] As Us On MRM.AddedBy=Us.UserId
                        LEFT JOIN dbo.EmployeeInformation As Em On Us.EmployeeId=Em.SystemId
                        LEFT JOIN [ORG].[Department] AS Dp On Dp.Id=Em.DepartmentId
						LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
                        LEFT JOIN TRN.PurchaseOrderDetail AS POD ON POD.RequisitionDetailId= MRD.Id
                        LEFT JOIN TRN.InventoryReceiveDetail IRD ON IRD.PODetailsId=POD.Id
                        --LEFT JOIN (Select Id,Sum(TransactionQty) TransactionQty,Sum(ApprovedQty) ApprovedQty,Sum(RejectionQty) RejectionQty from TRN.InventoryReceiveDetail group by Id) outIDR ON outIDR.Id=IRD.Id
                        LEFT JOIN(Select InventoryReceiveDetailId,Sum(TransactionQty) TransactionQty, Sum(RejectQty) RejectionQty from TRN.GRNPORequisitionAllocation group by  InventoryReceiveDetailId) outIDR ON outIDR.InventoryReceiveDetailId=IRD.Id
                        --LEFT JOIN (Select ID, Sum(ApprovedQty) Valid, sum(RejectionQty) RejectionQty1 from TRN.InventoryReceiveDetail group by ID) Appnext ON Appnext.Id !=outIDR.InventoryReceiveDetailId
                        --LEFT JOIN(select RequisitionId from TRN.RequisitionIssueDetail R
                        --left join TRn.InventoryIssue  II ON II.Id=R.IssueMasterId
                        --LEFT JOIN TRN.IssueRequest IR ON IR.Id=R.IssueRequestId) remreq ON remreq.RequisitionId=MRM.Id
                       Left JOIN (SELECT MRD.MaterialReqqusitionMasterId, MRD.Id AS RequisitionDetailId ,sum(RID.IssueQty) IssueQty, sum(RID.IssueRejectedQty) IssueRejectedQty
									FROM TRN.RequisitionIssueDetail RID
									Left JOIn TRN.InventoryIssue II ON II.Id=RID.IssueMasterId
									LEFT JOIN TRN.InventoryIssueDetail IID ON IID.Id=RID.IssueDetailId
									Left JOIN TRN. IssueRequest IR ON IR.Id=RID.IssueRequestId
									Left JOIN TRN.MaterialRequsitionDetails MRD On MRD.id=IR.RequisitionDetailId
									Group By MRD.MaterialReqqusitionMasterId, MRD.Id
									) IssuedQtyOut ON IssuedQtyOut.RequisitionDetailId=MRD.Id

                       LEFT JOIN(
						
								   SELECT IRD.Id,IM.MaterialMasterId,IM.ArticleId,IM.FirstCharacteristicsValueId,IM.SecondCharacteristicsValueId,IM.ThirdCharacteristicsValueId,Sum(IRD.ApprovedQty) TotalQty	
									FROM TRN.GRNPORequisitionAllocation GRNAll
									LEFT JOIN TRN.InventoryReceiveDetail IRD ON IRD.Id=GRNAll.InventoryReceiveDetailId
									LEFT JOIN TRN.InventoryMaterial IM  ON IM.Id=IRD.InventoryMaterialId
									Group BY IRD.Id,IM.MaterialMasterId,IM.ArticleId,IM.FirstCharacteristicsValueId,IM.SecondCharacteristicsValueId,IM.ThirdCharacteristicsValueId
								 ) outIDR1 ON  outIDR1.Id=outIDR.InventoryReceiveDetailId
                       Where  MRM.PlantId='" + identity.PlantId + @"'  
                       --AND  remreq.RequisitionId !=MRM.Id";

                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }
        public IEnumerable<object> IssueFilter()
        {
            try
            {
                var sql = @"Select 
                            ROW_NUMBER() OVER(ORDER BY IR.Id ASC) AS SiNo
                            ,IR.Id AS IssueRequestId
                            ,CC.UserName AS CostCenterName
                            ,IR.CostCenterId
                            ,B.UserName ActivityName 
                            ,IR.ExpenseActivityId
                            ,mm.UserName MaterialMasterName
							,MRD.MaterialMasterId InventoryMaterialId
                            ,ART.StandardName
                            ,ART.Code
							,MRD.TransactionUoMId
                            ,IR.RequisitionId
                            ,IR.RequisitionDetailId
                            ,TUoM.UserName AS UOM
                            ,IR.RequestedQty
                            ,IR.RejectedQty
                            ,Isnull(En.Username,'') As EntityName
                            ,MRM.EntityId	
                            ,Us.FullName AddedBy
                            ,MRM.Id RequisitionNo
                            ,MRD.ArticleId
                            ,Dp.UserName DepartmentName
                            ,MGM.UserName MaterialMasterGroupName
                            ,MT.UserName MaterialType
                            ,MRD.FirstCharacteristicsId
                            ,FC.UserName AS FirstCharacteristics
                            ,MRD.FirstCharacteristicsValueId
                            ,FCV.UserName AS FirstCharacteristicsValue
                            ,MRD.SecondCharacteristicsId
                            ,SC.UserName AS SecondCharacteristics
                            ,MRD.SecondCharacteristicsValueId
                            ,SCV.UserName AS SecondCharacteristicsValue
                            ,MRD.ThirdCharacteristicsId
                            ,TC.UserName AS ThirdCharacteristics
                            ,MRD.ThirdCharacteristicsValueId
                            ,TCV.UserName AS ThirdCharacteristicsValue
                            ,IR.CostCenterId
                            ,IR.ExpenseActivityId
                            ,IR.BudgetMasterId
                            ,IR.GLGeneralInfoId 
                            ,IR.RequisitionDetailId
							,IR.IssueRequestMasterId,B.UserName ExpenseActivityName
                            from trn.IssueRequest IR
                            left Join [TRN].[MaterialRequsitionDetails] As MRD on MRD.Id=IR.REquisitionDetailId
                            Left Join [TRN].[MaterialRequsitionMaster] As MRM On MRD.MaterialReqqusitionMasterId=MRM.Id
                            Left Join [ORG].[CostCenter] CC On CC.Id=IR.CostCenterId
                            Left Join hkp.Budget B On B.Id=IR.ExpenseActivityId
                            Left Join [ORG].[Entity] As En On MRM.EntityId=En.Id
                            Left Join [HKP].[Budget] As Bu On Bu.Id=MRD.ActivityId
                            Left JOIN MST.MaterialMaster AS MM ON MRD.MaterialMasterId = MM.Id
                            LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
                            LEFT JOIN MST.MaterialMasterArticle AS ART ON MRD.ArticleId = ART.Id
                            LEFT JOIN HKP.Characteristics AS FC ON MRD.FirstCharacteristicsId = FC.Id
                            LEFT JOIN HKP.Characteristics AS SC ON MRD.SecondCharacteristicsId = SC.Id
                            LEFT JOIN HKP.Characteristics AS TC ON MRD.ThirdCharacteristicsId = TC.Id
                            LEFT JOIN HKP.CharacteristicsValue AS FCV ON MRD.FirstCharacteristicsValueId = FCV.Id
                            LEFT JOIN HKP.CharacteristicsValue AS SCV ON MRD.SecondCharacteristicsValueId = SCV.Id
                            LEFT JOIN HKP.CharacteristicsValue AS TCV ON MRD.ThirdCharacteristicsValueId = TCV.Id
                            LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MRD.TransactionUoMId = TUoM.Id
                            LEFT JOIN [SEC].[User] As Us On MRM.AddedBy=Us.UserId
                            LEFT JOIN dbo.EmployeeInformation As Em On Us.EmployeeId=Em.SystemId
                            LEFT JOIN [ORG].[Department] AS Dp On Dp.Id=Em.DepartmentId
                            LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
	                        LEFT JOIN trn.IssueRequestMaster AS IRM ON IRM.Id = IR.IssueRequestMasterId                            
							where IRM.AuthorizedByStatus = 'Approval'";
                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }

