                --,FCV.UserName AS FirstCharacteristicsValue
                --,IOM.SecondCharacteristicsValueId
                --,SCV.UserName AS SecondCharacteristicsValue
                --,IOM.ThirdCharacteristicsValueId
                --,TCV.UserName AS ThirdCharacteristicsValue
                --,SC.Id SecondCharId
                --, SC.UserName SecondChar
                --, TC.Id ThirdCharId
                --, TC.UserName ThirdChar


                 , tg.Code AS TaxCode,IST.Percentage, IST.TaxAmount
                  FROM trn.InventorySalesTax IST
                LEFT OUTER JOIN[MST].[TaxCategory] TG ON tg.Id=IST.TaxCategoryId
                left join trn.InventorySalesHistory ISH ON ISH.Id= IST.InventorySalesHistoryId
