            {
                strSQL = @"select IRD.InventorySalesId,PO.Id PurchaseOrderId,tg.Code AS TaxCode,IRT.Percentage, IRT.TaxAmount 
                     from [TRN].[InventorySales] PO
                               INNER JOIN TRN.InventorySalesDetail IRD ON IRD.InventorySalesId = PO.Id
                               Inner join [TRN].[InventorySalesTax] IRT ON IRT.InventorySalesId = PO.Id 
